							data: [null,{type:"data",data:{product:{name:"Iristick.Assist",color_class:"assist",url:"https://iristick.com/products/Iristick.Assist/",meta_title:"Iristick.Assist – Remote Support With Zero Setup | Iristick",meta_description:"Bring a remote expert into the field in seconds. Share a link, they join in their browser — no app, no account needed. Hands-free with Iristick.",short_description:"is the fastest, simplest way to bring a remote expert into the field. Hands-free, no setup, no accounts.",long_description:"The wearer starts a call from the phone app and shares an invite link. The expert opens it in their browser and takes over from there. The wearer keeps both hands on the work and sees the expert's guidance directly in their view, with nothing to operate and nothing stored once the call ends.",category:"Remote Assistance",video_url:null,video_poster:"",image_url:"/_app/immutable/assets/assist.SHeORdFk.webp",value_header:"Why Choose \u003Cspan class=\"bold\">Iristick.Assist?\u003C/span>",values:[{name:"1. Connect in seconds, with anyone",description:"Send a link, your expert joins in their browser. No app, no account, no IT involvement on either side. Works whether they are across the building or across the world.",score:{}},{name:"2. Effortless for the wearer",description:"Once the call is started from the phone, the expert takes control of the session. The wearer has nothing to operate and nothing to remember. They keep their hands on the job and let the expert drive the view.",score:{}},{name:"3. Private by design",description:"Your conversations and what you see stay between you and your expert. Nothing routes through our servers and nothing is stored after the call ends.",score:{}},{name:"4. Made for live field decisions",description:"Bring your customer, a specialist, and your field team into the same view. The right people decide together, in the moment, without waiting for the next site visit.",score:{}}],get_started:"Set up hands-free remote assistance in minutes",steps:[{name:"1. Download",description:"Install the Iristick.Assist app on your iOS/Android phone and connect your Iristick smart glasses. Setup takes a couple of seconds."},{name:"2. Share",description:"Start a session in the app and generate a unique link. Send it to your expert. They join in their browser, with no sign-in required."},{name:"3. Collaborate",description:"Your expert takes over the session and guides you hands-free in real time, so issues get resolved without anyone leaving the field."}],quote:{author:"Patrick Colpaert",job_title:"Contract Manager Technical Maintenance Services",company:"Engie",logo:"/_app/immutable/assets/engie.DnIKE3g0.webp",avatar:"",quote:"\"It takes time before new technicians know all the locations, the installation setups and maintenance settings. Confronted with a problem on-site they cannot fix immediately, they used to call me to explain the problem over the phone and ask for help. Quite often, I had to jump in my car and go to the problem site to help the technician. This means travel time for me, waiting time for the mechanic and most importantly operational down-time for the client.\""},industries:[{icon:"construction",description:"On-site issue resolution in \u003Cspan class=\"bold\">construction and engineering\u003C/span>."},{icon:"orders",description:"Instant expert support for asset failures in \u003Cspan class=\"bold\">utilities and energy\u003C/span>."},{icon:"source_environment",description:"Remote oversight during compliance checks in \u003Cspan class=\"bold\">process industries\u003C/span>."},{icon:"emergency",description:"Live clinical guidance for distributed \u003Cspan class=\"bold\">healthcare\u003C/span> teams."},{icon:"precision_manufacturing",description:"Real-time troubleshooting on the line in \u003Cspan class=\"bold\">manufacturing\u003C/span>."},{icon:"support_agent",description:"After-sales support without site visits for \u003Cspan class=\"bold\">equipment vendors\u003C/span>."